const ANSWER_INDEXES = [0, 1, 2, 3, 1, 3, 2, 0, 2, 1];

export function createDoctorCourse(courseId) {
  const definition = courseCatalog[courseId];
  if (!definition) {
    throw new Error(`No Doctor course content is defined for ${courseId}.`);
  }

  const questions = definition.lessons.map(
    ([, , , , question, answers, correct, explanation], index) => {
      const balancedAnswers = [...answers];
      const correctAnswer = balancedAnswers.splice(correct, 1)[0];
      const answerIndex = ANSWER_INDEXES[index];
      balancedAnswers.splice(answerIndex, 0, correctAnswer);

      return {
        lessonId: `${courseId}-${index + 1}`,
        question,
        answers: balancedAnswers,
        correct: answerIndex,
        explanation,
      };
    },
  );

  const lessons = definition.lessons.map(
    ([title, objective, description, example], index) => {
      const question = questions[index];

      return {
        id: `${courseId}-${index + 1}`,
        title,
        subtitle: 'About 5 minutes',
        contentTitle: objective,
        description,
        sections: [
          { heading: 'Learning objective', text: objective },
          { heading: 'Core idea', text: description },
          { heading: 'Worked example', text: example },
        ],
        keyPoints: [objective, description, `Example: ${example}`],
        activities: [
          {
            type: 'quickCheck',
            question: question.question,
            options: question.answers,
            correct: question.correct,
            hint: 'Return to the lesson objective and compare it with the example.',
            explanation: question.explanation,
          },
        ],
      };
    },
  );

  return {
    id: courseId,
    ...definition,
    prerequisites: 'No prior medical or science study is expected; this is a beginner-level educational orientation.',
    passingPercent: 70,
    quizSize: 10,
    lessons,
    questions,
  };
}
